{"path": "outline.json", "content": "{
  "act_one": {
    "description": "第一幕（0-1500字）：建立军区大院的规则世界观，引入两位主角登场，新婚夜两人认出彼此却装作陌生，核心冲突初步显现。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "红喜字下的陌生人",
        "core_event": "苏晚按照组织安排嫁给少将陆霆，新婚夜两人在军区大院的新房独处，两人都从细节里认出了对方是失散十年的青梅竹马，却都遵守规则装作陌生人，完成了表面的新婚流程。",
        "emotional_tone": "压抑、试探",
        "key_scenes": [
          "苏晚站在贴满红喜字的新房里，看着窗外持枪巡逻的岗哨，意识到电话随时可能被监听",
          "陆霆穿着军装进门，两人礼貌握手，指尖接触的瞬间都下意识避开",
          "两人共同翻看结婚证上拍了十遍才过审的证件照，照片上两人都笑得标准又疏离",
          "陆霆洗漱时苏晚看到他后颈的旧疤，确认他就是自己以为早已战死的青梅竹马阿霆"
        ]
      }
    ],
    "turning_point": "苏晚确认陆霆的身份，两人心照不宣的伪装正式开始。"
  },
  "act_two": {
    "description": "第二幕（1500-5000字）：两人的共同生活中互相试探，旧情在压抑中复燃，规则的压迫感逐渐升级，两人成为秘密的共犯。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "暗语与伤疤",
        "core_event": "陆霆用当年的战场暗语和苏晚交流避免被监听，苏晚发现陆霆背上的枪伤是当年为她挡的，陆霆却只说是训练受伤，两人感情在拉扯中升温。",
        "emotional_tone": "拉扯、悸动",
        "key_scenes": [
          "陆霆教苏晚用当年的手势报平安，那些曾经用来传递作战指令的手势，现在用来问她有没有吃饭、说想她",
          "苏晚帮陆霆处理背上的旧伤，发现枪伤的位置和十年前他替自己挡枪的位置完全一致",
          "两人在哨兵换岗的间隙第一次接吻，全程捂着对方的嘴不敢发出一点声音",
          "张政委打电话询问两人生活情况，两人默契扮演恩爱夫妻，挂了电话之后沉默相对无言"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "共犯",
        "core_event": "两人越来越沉迷于规则缝隙里的亲密，甚至在哨兵巡逻时安静做爱，用手势传递情绪，成为彼此秘密的共犯。",
        "emotional_tone": "禁忌、浓烈",
        "key_scenes": [
          "苏晚在结婚证背面悄悄写下当年两人的暗号，陆霆发现后也写下了回应的回应，假装不知道是谁写的",
          "陆霆执行任务回来，两人在客厅拥吻，听到岗哨脚步声立刻分开装作讨论工作",
          "亲热时听到窗外巡逻的脚步声，两人捂着对方的嘴，连呼吸都放得极轻",
          "张政委通知两人下周要作为模范夫妻在军区夫妻表彰大会发言，分享相识相爱的过程"
        ]
      }
    ],
    "turning_point": "两人面临公开编造谎言公开表演恩爱，要么承认旧情身败名裂的两难抉择。"
  },
  "act_three": {
    "description": "第三幕（5000-8000字）：高潮和结局，两人选择继续伪装，永远不承认旧情，BE结局。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "永远的陌生人",
        "core_event": "两人在表彰大会上完美扮演模范夫妻，分享编造的相识故事获得全场掌声，回到家后默契地继续做相敬如宾的政治夫妻，永远封存了所有旧情，永远不能宣之于口。",
        "emotional_tone": "虐心、遗憾",
        "key_scenes": [
          "两人在家排练发言稿，看着对方的眼睛，念着完全编造的相识过程，指尖微微发抖",
          "表彰大会上苏晚挽着陆霆的胳膊，脸上带着标准的微笑，在他手心写下“我爱过你”",
          "回到家后两人把结婚证放回抽屉，把写了暗号的那一面朝下压着",
          "苏晚看着窗外的岗哨，陆霆站在她身边，两人都没有说话，仿佛从来只是陌生人"
        ]
      }
    ]
  }
}"}

environment.content:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "characters.schema.json",
  "title": "小说人物设计",
  "description": "人物一致性的参考依据，避免角色崩坏",
  "type": "object",
  "required": ["main_characters"],
  "properties": {
    "main_characters": {
      "type": "array",
      "description": "主角/核心角色数组",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": [
          "name",
          "role",
          "traits",
          "overt_motivation",
          "covert_motivation",
          "secret_fear"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "角色姓名"
          },
          "role": {
            "type": "string",
            "enum": ["protagonist", "deuteragonist"],
            "description": "角色类型：protagonist=第一主角，deuteragonist=第二主角"
          },
          "identity": {
            "type": "string",
            "description": "身份职业/社会角色"
          },
          "traits": {
            "type": "array",
            "description": "核心性格特质关键词（3-5个）",
            "items": {
              "type": "string"
            },
            "minItems": 3,
            "maxItems": 5
          },
          "overt_motivation": {
            "type": "string",
            "description": "显性动机（表面目标）"
          },
          "covert_motivation": {
            "type": "string",
            "description": "隐性动机（深层需求）"
          },
          "secret_fear": {
            "type": "string",
            "description": "秘密恐惧（内心脆弱点）"
          },
          "misperception_of_other": {
            "type": "string",
            "description": "对其他主角的错位认知"
          },
          "hidden_connection": {
            "type": "string",
            "description": "与其他角色的隐藏连接"
          }
        }
      }
    },
    "supporting_characters": {
      "type": "array",
      "description": "配角/次要角色数组",
      "items": {
        "type": "object",
        "required": ["name", "function"],
        "properties": {
          "name": {
            "type": "string",
            "description": "配角姓名"
          },
          "function": {
            "type": "string",
            "enum": ["助力", "阻碍", "反转点"],
            "description": "对主角的作用类型"
          },
          "identity": {
            "type": "string",
            "description": "配角身份"
          },
          "description": {
            "type": "string",
            "description": "配角简要描述"
          }
        }
      }
    },
    "relationship_dynamics": {
      "type": "string",
      "description": "角色关系动态描述"
    }
  }
}

{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "creative_intent.schema.json",
  "title": "小说创作意图配方",
  "description": "记录用户需求理解和配方选择结果，作为创作的北极星",
  "type": "object",
  "required": ["user_need", "inspiration_state", "extracted_elements", "selected_recipe", "one_sentence_synopsis"],
  "properties": {
    "user_need": {
      "type": "string",
      "description": "用户的原始输入文本",
      "minLength": 1
    },
    "inspiration_state": {
      "type": "string",
      "enum": ["no_inspiration", "vague_inspiration", "clear_inspiration"],
      "description": "用户创作时的灵感清晰程度"
    },
    "extracted_elements": {
      "type": "object",
      "description": "从用户输入中提取的创作关键要素",
      "required": ["emotion_verbs", "scene_elements", "relationship_tension"],
      "properties": {
        "emotion_verbs": {
          "type": "array",
          "description": "情感动词/核心动作（决定X轴剧情模式）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "scene_elements": {
          "type": "array",
          "description": "场景要素/世界观元素（决定Y轴标签）",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "relationship_tension": {
          "type": "array",
          "description": "人物关系张力/冲突来源",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "user_preferences": {
          "type": "object",
          "description": "用户的情感偏好和禁忌",
          "properties": {
            "desired_emotion": {
              "type": "string",
              "description": "期望的情感倾向"
            },
            "forbidden": {
              "type": "array",
              "description": "明确拒绝的元素",
              "items": {
                "type": "string"
              }
            }
          }
        }
      }
    },
    "selected_recipe": {
      "type": "object",
      "description": "用户选定的创作配方（X-Y轴化学反应组合）",
      "required": [
        "x_axis_mode_id",
        "x_axis_mode_name",
        "y_axis_tags",
        "reaction_strength",
        "tension_stars",
        "forbidden_elements"
      ],
      "properties": {
        "x_axis_mode_id": {
          "type": "string",
          "pattern": "^[A-G]\\d{1,2}$",
          "enum": [
            "A1", "A2", "A3", "A4", "A5", "A6",
            "B7", "B8", "B9", "B10", "B11", "B12",
            "C13", "C14", "C15", "C16", "C17", "C18",
            "D19", "D20", "D21", "D22", "D23",
            "E24", "E25", "E26", "E27", "E28",
            "F29", "F30", "F31", "F32", "F33", "F34",
            "G35", "G36"
          ],
          "description": "普罗蒂36种剧情模式的标识符"
        },
        "x_axis_mode_name": {
          "type": "string",
          "description": "X轴模式的中文名称"
        },
        "y_axis_tags": {
          "type": "array",
          "description": "现代网文核心标签（表达载体）",
          "items": {
            "type": "string",
            "enum": [
              "双向暗恋",
              "系统流",
              "无限流",
              "种田流",
              "赛博朋克",
              "规则怪谈",
              "重生/穿越",
              "商战权谋",
              "克苏鲁",
              "第四天灾",
              "仙侠修真",
              "刑侦悬疑"
            ]
          },
          "minItems": 2,
          "maxItems": 3
        },
        "reaction_strength": {
          "type": "string",
          "enum": ["↗", "↘", "✷"],
          "description": "X轴与Y轴的化学反应强度符号"
        },
        "tension_stars": {
          "type": "integer",
          "minimum": 1,
          "maximum": 5,
          "description": "故事张力指数（1-5星）"
        },
        "forbidden_elements": {
          "type": "array",
          "description": "避雷红线（创作禁忌元素）",
          "items": {
